import * as THREE from './vendor/three.module.js';
export const SCAN_WAIT=1.8, MOTION_SECONDS=15, STAGE_SECONDS=3, CYCLE_SECONDS=16.8;
export function visionClock(time){const step=Math.floor(time/CYCLE_SECONDS),within=time-step*CYCLE_SECONDS;return {step,within,motionTime:step*MOTION_SECONDS+Math.max(0,within-SCAN_WAIT),waiting:within<SCAN_WAIT,phase:within<.9?0:within<1.55?1:within<SCAN_WAIT?2:3,progress:Math.min(1,within/SCAN_WAIT),cloudProgress:THREE.MathUtils.clamp((within-.6)/.95,0,1)};}
export function presentationTime(motionTime){const step=Math.floor(motionTime/MOTION_SECONDS),rest=motionTime-step*MOTION_SECONDS;return step*CYCLE_SECONDS+(rest<1e-8?0:SCAN_WAIT+rest);}
// Sample first visible surfaces, rather than drawing a flat synthetic sheet.
export function sampleSurfaces(origin,center,width,depth,objects,columns=29,rows=23){const ray=new THREE.Raycaster(),hits=[];for(let r=0;r<rows;r++)for(let c=0;c<columns;c++){const aim=new THREE.Vector3(center.x+(c/(columns-1)-.5)*width,center.y,center.z+(r/(rows-1)-.5)*depth);ray.set(origin,aim.sub(origin).normalize());const hit=ray.intersectObjects(objects,false)[0];if(hit){const normal=hit.face?hit.face.normal.clone().transformDirection(hit.object.matrixWorld):new THREE.Vector3(0,1,0);hits.push({point:hit.point.clone().addScaledVector(normal,.009),object:hit.object,distance:hit.distance});}}return hits;}
function pointsMaterial(size,opacity=1){return new THREE.PointsMaterial({color:'#64ffce',size,transparent:true,opacity,depthWrite:false,blending:THREE.AdditiveBlending});}
export function createVisionScan(station){const root=new THREE.Group();root.userData.scanEffect=true;station.content.add(root);const beamGeo=new THREE.BufferGeometry(),beam=new THREE.Mesh(beamGeo,new THREE.MeshBasicMaterial({color:'#44e9bc',transparent:true,opacity:.06,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));root.add(beam);const lines=new THREE.LineSegments(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#6effd2',transparent:true,opacity:.2,depthWrite:false,blending:THREE.AdditiveBlending}));root.add(lines);const spots=new THREE.Points(new THREE.BufferGeometry(),pointsMaterial(.065,.8));root.add(spots);station.cloud.material.dispose();station.cloud.material=pointsMaterial(.037);const light=new THREE.SpotLight('#55ffd0',0,10,.34,.2,1.5);light.position.set(station.source.x,station.mount-.1,station.source.z);light.target.position.set(station.source.x,0,station.source.z);root.add(light,light.target);const lens=new THREE.Mesh(new THREE.CylinderGeometry(.065,.065,.018,20),new THREE.MeshBasicMaterial({color:'#aaffeb'}));lens.position.set(0,-.091,0);station.cam.add(lens);return {root,beam,lines,spots,light,lens,step:null,mount:null,count:0,hits:[]};}
function visible(o){for(let n=o;n;n=n.parent)if(!n.visible)return false;return true;}
function capture(s){const v=s.scan,head=s.scanHead,x=head.x,z=head.z,height=head.primary?s.mount:head.height;head.cam.add(v.lens);s.root.updateWorldMatrix(true,true);const origin=head.cam.getWorldPosition(new THREE.Vector3());origin.y-=.1;const center=s.content.localToWorld(new THREE.Vector3(x,.035,z));const objects=[];s.content.traverse(o=>{if(!o.isMesh||!visible(o)||o.material?.transparent)return;for(let n=o;n&&n!==s.content;n=n.parent){if(n.userData.part==='camera'||n===v.root||n===s.fv)return;}if(o===s.post||o===s.cross||o===s.cantilever)return;objects.push(o);});if(s.floorMesh)objects.push(s.floorMesh);const width=height*.54,depth=height*.42;const hits=sampleSurfaces(origin,center,width,depth,objects),positions=[],colors=[],rays=[];for(let i=0;i<hits.length;i++){const p=s.content.worldToLocal(hits[i].point.clone());positions.push(p.x,p.y,p.z);const shade=Math.max(0,Math.min(1,p.y/2.2));colors.push(.2+shade*.5,.98,.85-shade*.35);if(i%23===0)rays.push(x,height-.1,z,p.x,p.y,p.z);}v.hits=hits;v.count=hits.length;const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));s.cloud.geometry.dispose();s.cloud.geometry=geometry;s.cloud.material.vertexColors=true;v.spots.geometry.dispose();v.spots.geometry=geometry.clone();v.lines.geometry.dispose();v.lines.geometry=new THREE.BufferGeometry();v.lines.geometry.setAttribute('position',new THREE.Float32BufferAttribute(rays,3));const w=height*.9/2,d=height*.7/2,corners=[[x-w,.035,z-d],[x+w,.035,z-d],[x+w,.035,z+d],[x-w,.035,z+d]],triangles=[];for(let i=0;i<4;i++)triangles.push(x,height-.1,z,...corners[i],...corners[(i+1)%4]);v.beam.geometry.dispose();v.beam.geometry=new THREE.BufferGeometry();v.beam.geometry.setAttribute('position',new THREE.Float32BufferAttribute(triangles,3));v.light.position.set(x,height-.1,z);v.light.target.position.set(x,0,z);}
export function updateVisionScan(s,clock,retainCloud=false){const v=s.scan;if(v.step!==clock.step||v.mount!==s.mount||v.head!==s.scanHead){capture(s);v.step=clock.step;v.mount=s.mount;v.head=s.scanHead;}const lit=clock.within<.9,pulse=1;v.beam.visible=lit;v.lines.visible=lit;v.spots.visible=lit;v.spots.geometry.setDrawRange(0,Math.max(1,Math.ceil(v.count*Math.min(1,(clock.within+.15)/.8))));v.spots.material.opacity=.85*pulse;v.light.intensity=lit?9*pulse:0;v.lens.visible=lit;const auto=clock.within>=.6&&clock.within<2.25;s.cloud.visible=retainCloud||auto;s.cloud.material.opacity=clock.waiting||retainCloud?.95:Math.max(0,(2.25-clock.within)/.45)*.75;s.cloud.geometry.setDrawRange(0,Math.ceil(v.count*clock.cloudProgress));return v.count;}
